import{_ as o,o as a,c as t,a2 as r}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse('{"title":"Importare ed esportare","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/import-export.md","filePath":"user-guide/import-export.md"}'),i={name:"user-guide/import-export.md"};function n(l,e,s,c,p,u){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="importare-ed-esportare" tabindex="-1">Importare ed esportare <a class="header-anchor" href="#importare-ed-esportare" aria-label="Permalink to &quot;Importare ed esportare&quot;">​</a></h1><h2 id="importare" tabindex="-1">Importare <a class="header-anchor" href="#importare" aria-label="Permalink to &quot;Importare&quot;">​</a></h2><p><em>Importa…</em> (palette comandi) apre una procedura guidata in più passi:</p><ol><li><strong>Sorgente:</strong> cartella Markdown/HTML (o zip), Evernote (ENEX), Notion (esportazione Markdown/CSV in zip), Roam, Bear, Google Keep (Takeout), CSV. L&#39;app riconosce la sorgente dal contenuto e propone quella probabile.</li><li><strong>Opzioni:</strong> cartella di destinazione nel vault, conversione dei link in <code>[[wikilink]]</code>, cartella degli allegati, inclusione di note archiviate o nel cestino, e per i CSV delimitatore, colonna del titolo e del corpo (le altre colonne diventano proprietà).</li><li><strong>Anteprima:</strong> quante note e allegati verranno creati e un campione dei titoli, con eventuali avvisi. <strong>Non viene scritto nulla</strong> finché non premete <em>Importa</em>.</li><li><strong>Avanzamento e report:</strong> al termine un riepilogo (note e allegati creati, link riscritti, elementi saltati o falliti) e una nota di report apribile.</li></ol><p>Garanzie: l&#39;importazione <strong>non sovrascrive mai</strong> note esistenti (in caso di nome uguale ne crea di nuove con un suffisso); se la annullate, quanto già scritto resta; gli archivi vengono controllati contro file malevoli (percorsi fuori cartella, archivi &quot;bomba&quot;, XML esterno).</p><h2 id="esportare-una-nota" tabindex="-1">Esportare una nota <a class="header-anchor" href="#esportare-una-nota" aria-label="Permalink to &quot;Esportare una nota&quot;">​</a></h2><ul><li><strong>PDF:</strong> <em>Esporta in PDF</em> apre la finestra di stampa del sistema: scegliete &quot;Salva come PDF&quot;.</li><li><strong>HTML:</strong> <em>Esporta in HTML</em> salva un file <strong>autonomo</strong> (immagini incorporate, formule e diagrammi già renderizzati, nessuna risorsa remota). Gli elementi che non possono stare in un documento autonomo e quelli troppo grandi sono elencati nell&#39;avviso finale.</li></ul><h2 id="esportare-un-vault" tabindex="-1">Esportare un vault <a class="header-anchor" href="#esportare-un-vault" aria-label="Permalink to &quot;Esportare un vault&quot;">​</a></h2><ul><li><strong>Vault locale:</strong> i file sono già normali file nella cartella: copiatela dove volete.</li><li><strong>Vault del cloud, dalla Web UI</strong> (pagina <em>Vault</em>): <em>Scarica ZIP</em>, con lo stesso testo per ogni vault (per un vault privato i lettori di schermo leggono anche «decifrato nel tuo browser»). <ul><li><em>Condiviso:</em> lo ZIP è generato dal server (per vault grandi in background: lo stato passa da &quot;in coda&quot; a &quot;pronto&quot; e il download parte da solo).</li><li><em>Privato:</em> lo ZIP è costruito <strong>nel vostro browser</strong>, dopo aver inserito passphrase o chiave di recupero; il server non vede mai i contenuti. Non chiudete la scheda finché non termina.</li></ul></li><li><strong>Come è fatto lo ZIP.</strong> Contiene i file correnti del vault con i loro percorsi, senza le parti che appartengono al dispositivo (indice di ricerca, stato di sincronizzazione, disposizione delle schede, cache e istantanee locali). Le impostazioni condivise stanno in <strong><code>.clarae/</code></strong>: se un vault era stato usato con la versione 1.x e ha ancora la cartella di configurazione di allora (il nome è in <a href="./installazione.html#aggiornare-dalla-1x">Aggiornare dalla 1.x</a>), i suoi file escono sotto <code>.clarae/</code> e, se lo stesso nome esiste in entrambe, <strong>vince <code>.clarae/</code></strong>. Vale per lo ZIP del server e per quello di un vault privato costruito nel browser.</li><li>Dall&#39;app: <em>Esporta vault come ZIP</em>.</li></ul>',9)])])}const g=o(i,[["render",n]]);export{m as __pageData,g as default};
